result = []
for sid, title, typ, date, themes, total, extras, desc, stamps in S:
    item = {
        "id": sid, "title": title, "type": typ, "issueDate": date,
        "year": 2018, "series": "编年", "themes": themes, "designer": "",
        "totalStamps": total, "extras": extras, "description": desc, "stamps": []
    }
    for sn, name, den, img, fmt in stamps:
        entry = {"sn": sn, "name": name, "denomination": den, "image": img}
        if fmt:
            entry["format"] = fmt
        item["stamps"].append(entry)
    result.append(item)

with open("data/stamps/2018.json", "w", encoding="utf-8") as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

total_stamps = sum(len(item["stamps"]) for item in result)
total_regular = sum(item["totalStamps"] for item in result)
print(f"done: {len(result)} sets, {total_regular} regular stamps, {total_stamps} total entries")
